Example usage (synchronous):

```r
library(elmer)

chat <- new_chat_openai(quiet = TRUE)


# Sync non-streaming
cat(chat$chat("What are the pros/cons of 1440p vs 4K in a 27\" monitor?"))


# Sync streaming, with coro
coro::loop(for (chunk in chat$stream("What are the pros/cons of 1440p vs 4K in a 27\" monitor?")) {
  cat(chunk)
})
cat("\n")


# Sync streaming, with base R
resp <- chat$stream("What are the pros/cons of 1440p vs 4K in a 27\" monitor?")
repeat {
  chunk <- resp()
  if (coro::is_exhausted(chunk)) {
    cat("\n")
    break
  }
  cat(chunk)
}
```

Example usage (asynchronous):

```r
library(elmer)
library(promises)

chat <- new_chat_async_openai(quiet = TRUE)


# Async non-streaming
chat$chat("What are the pros/cons of 1440p vs 4K in a 27\" monitor?") %...>% cat()


# Async streaming, with coro
coro::async(function() {
  for (chunk in await_each(chat$stream("What are the pros/cons of 1440p vs 4K in a 27\" monitor?"))) {
    cat(chunk)
  }
})()


# Async streaming, with base R 😬
resp <- chat$stream("What are the pros/cons of 1440p vs 4K in a 27\" monitor?")
proceed <- function() {
  resp() |> then(\(chunk) {
    if (coro::is_exhausted(chunk)) {
      cat("\n")
    } else {
      cat(chunk)
      proceed()
    }
  })
}
proceed()
```

